// Both triggers land here already mapped to { storyId, repo, baseBranch }.
const input = $input.first().json;
const storyId = String(input.storyId ?? '').trim().toUpperCase();
// repo may be empty here: Extract Story then falls back to a "Repo: org/name" line in Notes
const repo = String(input.repo ?? '').trim().replace(/^https?:\/\/[^/]+\//, '').replace(/\.git$/, '').replace(/\/+$/, '');
const baseBranch = String(input.baseBranch ?? '').trim();

if (!/^US\d+$/.test(storyId)) throw new Error(`Rally story ID must look like US1234567, got "${storyId}"`);
if (repo && !/^[\w.-]+\/[\w.-]+$/.test(repo)) throw new Error(`repository must be org/name on GHE, got "${repo}"`);
if (baseBranch && !/^[\w./-]+$/.test(baseBranch)) throw new Error(`invalid base branch "${baseBranch}"`);

const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\..*$/, '').replace('T', '-');
return [{ json: { storyId, repo, baseBranch, runDir: `${storyId}-${stamp}` } }];

const input = $('Normalize & Validate').first().json;
const s = $input.first().json.result; // rally.sh get — fetched with the host's $RALLY_API_KEY

const text = (html) => String(html ?? '')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h\d)>/gi, '\n').replace(/<li[^>]*>/gi, '- ')
  .replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\n{3,}/g, '\n\n').trim();

const story = {
  formattedId: s.FormattedID,
  objectId: s.ObjectID,
  name: s.Name,
  scheduleState: s.ScheduleState,
  project: s.Project,
  feature: s.Feature,
  description: text(s.Description),
  acceptanceCriteria: text(s.c_AcceptanceCriteria),
  notes: text(s.Notes),
  url: `https://rally1.rallydev.com/#/detail/userstory/${s.ObjectID}`,
};

const storyText = [
  `# ${story.formattedId}: ${story.name}`,
  `Rally: ${story.url}`,
  story.feature && `Parent Feature: ${story.feature}`,
  story.project && `Rally Project: ${story.project}`,
  `Schedule State: ${story.scheduleState}`,
  '', '## Description', story.description || '(empty)',
  '', '## Acceptance Criteria', story.acceptanceCriteria || '(none recorded in c_AcceptanceCriteria — check the Description)',
  story.notes && `\n## Notes\n${story.notes}`,
].filter(Boolean).join('\n');

// No repo on the form -> look for "Repo: org/name" (and optional "Base: branch") in Notes.
let { repo, baseBranch } = input;
if (!repo) {
  const m = story.notes.match(/^\s*Repo:\s*(?:https?:\/\/[^/\s]+\/)?([\w.-]+\/[\w.-]+?)(?:\.git)?\s*$/mi);
  if (!m) throw new Error(`No repository given, and ${input.storyId}'s Notes have no "Repo: org/name" line`);
  repo = m[1];
  const b = story.notes.match(/^\s*Base:\s*([\w./-]+)\s*$/mi);
  if (!baseBranch && b) baseBranch = b[1];
}

return [{ json: { ...input, repo, baseBranch, story, storyText } }];

const c = $('Extract Story').first().json;
// Branch name is feature/<storyId>_<slug> — slug is the story title, non-alnum collapsed to '_'.
const slug = String(c.story.name || '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 50);
return [{ json: {
  kind: 'script',
  name: 'prepare-workspace',
  label: 'Prepare Workspace',
  args: [c.repo, c.baseBranch, c.storyId, c.runDir, slug],
  timeoutMin: 15,
} }];

// Shared context every Claude phase is prompted with.
const c = $('Extract Story').first().json;
const ws = $input.first().json.result; // prepare-workspace.sh JSON

const preamble = `You are running NON-INTERACTIVELY as one phase of an automated n8n pipeline:
Rally story -> CEC spec-kit delivery flow -> draft pull request.
Nobody is watching this session and nobody can answer questions. Never ask the user anything and
never wait for confirmation: make the best decision you can ground in the story, the repository
and cec-knowledge, and write that decision down where the phase says to.

Context:
- Working directory: a fresh clone of ${c.repo} (GHE), on branch ${ws.branch}, cut from ${ws.base}.
- Rally story: ${c.storyId} — ${c.story.name} (${c.story.url})
- spec-kit ${ws.specifyInitialized ? 'skills were just installed/refreshed in this repo by the pipeline' : 'was already set up in this repo'}${ws.constitutionMissing ? '; the repo has no real constitution yet' : ''}.

Rules for every phase:
- Follow the cec-sdlc:cec-deliver flow, but perform ONLY the phase described below — later
  phases run as separate sessions and rely on the files you leave on disk.
- Use cec-sdlc:cec-knowledge whenever you need CEC grounding (components, flows, standards, repo ownership).
- Do NOT run cec-finalize or cec-costs-telemetry. Do NOT create or update anything in Rally.
- Do NOT git push, open, update or merge pull requests — the pipeline does that after the last phase.`;

const statusRule = `
Finish your reply with one final line, exactly one of:
STATUS: OK
STATUS: BLOCKED: <one-line reason>
Use BLOCKED only when this phase cannot be completed correctly (for example the story is not
scoped to this repository, or a CRITICAL problem remains).`;

// Per-phase model policy (host `claude --model` strings). Development phases run on Opus 4.8;
// the cheap PR-body write runs on Haiku 4.5; any phase that fails is retried once on Opus 5.5
// (the newest model, so it doubles as the failover if a pinned id is ever retired).
const models = {
  dev: 'claude-opus-4-8',
  discovery: 'claude-haiku-4-5-20251001',
  retry: 'claude-opus-5-5',
};

return [{ json: { ...c, workspace: ws, preamble, statusRule, models } }];

const c = $('Build Context').first().json;
const phase = `PHASE 3/6 — plan.
Run the speckit-plan skill for the current feature. Ground the technical decisions in the
existing codebase (read it; match its structure, frameworks and test setup) and in cec-knowledge
(components, standards, NFRs). Reply with the list of artifacts you created.`;
return [{ json: {
  kind: 'claude',
  label: "Plan",
  model: c.models.dev,
  retryModel: c.models.retry,
  cwd: c.runDir,
  timeoutMin: 45,
  requireStatusOk: true,
  prompt: `${c.preamble}\n\n${phase}\n${c.statusRule}`,
} }];

const c = $('Build Context').first().json;
const phase = `PHASE 4/6 — tasks.
Run the speckit-tasks skill for the current feature, based on spec.md and plan.md. Tasks must be
concrete enough to implement without further questions, and must include the tests the CEC Test
Standard calls for at component level. Reply with the task count per phase.`;
return [{ json: {
  kind: 'claude',
  label: "Tasks",
  model: c.models.dev,
  retryModel: c.models.retry,
  cwd: c.runDir,
  timeoutMin: 30,
  requireStatusOk: true,
  prompt: `${c.preamble}\n\n${phase}\n${c.statusRule}`,
} }];

const c = $('Build Context').first().json;
const phase = `PHASE 5/6 — analyze.
Run the speckit-analyze skill for the current feature. It only reports. After it reports, fix
every CRITICAL and HIGH finding yourself by editing spec.md, plan.md and/or tasks.md, then run
speckit-analyze once more to confirm. Reply with the findings you fixed and any MEDIUM/LOW ones
you deliberately left. If a CRITICAL finding still remains after your fixes, report BLOCKED.`;
return [{ json: {
  kind: 'claude',
  label: "Analyze",
  model: c.models.dev,
  retryModel: c.models.retry,
  cwd: c.runDir,
  timeoutMin: 30,
  requireStatusOk: true,
  prompt: `${c.preamble}\n\n${phase}\n${c.statusRule}`,
} }];

const c = $('Build Context').first().json;
const body = String($('Write PR Body').first().json.result ?? '').trim();
if (body.length < 50) throw new Error('PR body from Claude is empty or too short — see the Write PR Body node output');
// Built here, not by Claude, so the PR always links the exact successful run.
const t = $('Parse Nonprod Target').first().json.target;
const qa = $('Parse Nonprod Target').first().json.qa ?? [];
let run = null;
try { run = $('Run Nonprod Plan').first().json.result; } catch (_) { /* skipped */ }
const qaText = qa.length ? `\n\nDeveloper answers (Slack):\n${qa.map((x) => `- **Q:** ${x.question.replace(/\n+/g, ' ')}\n  **A:** ${x.answer.replace(/\n+/g, ' ')}`).join('\n')}` : '';
const nonprod = t.skip
  ? `## Nonprod Terraform plan\nSkipped: the developer answered that this story needs no nonprod plan. ${t.rationale ?? ''}${qaText}`
  : `## Nonprod Terraform plan\n` +
    `:white_check_mark: **[Terraform plan run #${run.runId}](${run.runUrl})** against non-prod environment \`${t.environment}\` succeeded on this branch (commit \`${String(run.headSha).slice(0, 12)}\`${run.attempt > 1 ? `, attempt ${run.attempt}` : ''}).\n` +
    `- Workflow: \`${t.workflow}\` (${t.trigger})${Object.keys(t.inputs ?? {}).length ? `, inputs \`${JSON.stringify(t.inputs)}\`` : ''}\n` +
    `- Jobs: ${(run.jobs ?? []).map((j) => `[${j.name}](${j.url}) ${j.conclusion}`).join(', ')}\n` +
    (run.planStepSeen ? '' : `- :warning: no step named "plan" was seen in the run; check it really ran \`terraform plan\`\n`) +
    `- Why this environment: ${t.rationale ?? ''}` +
    ((t.evidence ?? []).length ? `\n- Evidence: ${t.evidence.join('; ')}` : '') + qaText;
const footer = `\n\n---\n_Draft PR opened by the n8n **Rally Story → Spec-Kit → Draft PR** workflow. Spec, plan, tasks and code were produced by Claude Code running the CEC spec-kit flow with no human input (the nonprod plan target excepted, where Claude could ask over Slack): review the autonomous-clarify assumptions before marking this ready._`;
return [{ json: {
  kind: 'script',
  name: 'open-pr',
  label: 'Open Draft PR',
  args: [c.runDir, `${c.storyId}: ${c.story.name}`.slice(0, 250), `${body}\n\n${nonprod}${footer}`],
  timeoutMin: 10,
} }];

const c = $('Build Context').first().json;
const pr = $('Open Draft PR').first().json.result;
let plan = null;
try { plan = $('Run Nonprod Plan').first().json.result; } catch (_) { /* skipped */ }
const ts = new Date().toISOString().replace('T', ' ').slice(0, 16) + 'Z';
return [{ json: {
  kind: 'script', name: 'rally-append-note', label: 'Note PR in Rally', timeoutMin: 2,
  args: [c.storyId, `[n8n ${ts}] Draft PR opened by the Rally → Spec-Kit → Draft PR workflow: ${pr.prUrl} (branch ${pr.branch} → ${pr.base})${plan ? `; nonprod Terraform plan passed: ${plan.runUrl}` : '; nonprod plan skipped'}`],
} }];

// Roll up cost + tokens across every Claude phase (every run of the looped nonprod phases) and
// append them to the story Notes as a minimal one-line section, for per-story traceability.
// Every run's output of a node (the nonprod loop can run a phase several times).
const runsOf = (n) => {
  const out = [];
  for (let r = 0; r < 50; r++) {
    let item;
    try { item = $(n).first(0, r); } catch (_) { break; }
    if (item) out.push(item.json);
  }
  return out;
};
const c = $('Build Context').first().json;
let cost = 0, inTok = 0, outTok = 0;
const parts = [];
for (const n of ['Seed + Specify', 'Clarify', 'Plan', 'Tasks', 'Analyze', 'Implement', 'Discover Nonprod Plan', 'Fix Nonprod Plan', 'Write PR Body']) {
  const runs = runsOf(n);
  if (!runs.length) continue;
  let pc = 0, pt = 0;
  for (const j of runs) {
    const u = j.usage || {};
    const i = (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0);
    const o = u.output_tokens || 0;
    pc += j.costUsd || 0; pt += i + o; inTok += i; outTok += o;
  }
  cost += pc;
  const retried = runs.some((j) => j.retried);
  parts.push(`${n}${runs.length > 1 ? ` ×${runs.length}` : ''} $${pc.toFixed(2)}/${pt}tok${retried ? ' (retried)' : ''}`);
}
const total = Math.round(cost * 100) / 100;
const ts = new Date().toISOString().replace('T', ' ').slice(0, 16) + 'Z';
const note = `[n8n ${ts}] AI usage for this run: $${total.toFixed(2)}, tokens ${inTok + outTok} (in ${inTok} / out ${outTok}). By phase — ${parts.join('; ')}.`;
return [{ json: { kind: 'script', name: 'rally-append-note', label: 'Note Cost in Rally', timeoutMin: 2, args: [c.storyId, note] } }];

// Every run's output of a node (the nonprod loop can run a phase several times).
const runsOf = (n) => {
  const out = [];
  for (let r = 0; r < 50; r++) {
    let item;
    try { item = $(n).first(0, r); } catch (_) { break; }
    if (item) out.push(item.json);
  }
  return out;
};
const c = $('Build Context').first().json;
const pr = $('Open Draft PR').first().json.result;
const target = $('Parse Nonprod Target').first().json.target;
let plan = null;
try { plan = $('Run Nonprod Plan').first().json.result; } catch (_) { /* skipped */ }
const tokensOf = (u) => (u ? ((u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.output_tokens || 0)) : 0);
const phases = ['Seed + Specify', 'Clarify', 'Plan', 'Tasks', 'Analyze', 'Implement', 'Discover Nonprod Plan', 'Fix Nonprod Plan', 'Write PR Body'].flatMap((name) => runsOf(name).map((j) => (
  { phase: name, model: (j.models || []).slice(-1)[0] ?? null, retried: j.retried ?? false, costUsd: j.costUsd, tokens: tokensOf(j.usage), sessionId: j.sessionId, startedAt: j.startedAt, finishedAt: j.finishedAt }
)));
const totalCostUsd = Math.round(phases.reduce((s, p) => s + (p.costUsd || 0), 0) * 100) / 100;
const totalTokens = phases.reduce((s, p) => s + (p.tokens || 0), 0);
return [{ json: {
  prUrl: pr.prUrl,
  nonprodPlan: target.skip ? { skipped: true } : { runUrl: plan?.runUrl, conclusion: plan?.conclusion, environment: target.environment, workflow: target.workflow, inputs: target.inputs },
  rallyNote: $('Note PR in Rally').first().json.result?.appended ?? null,
  storyId: c.storyId,
  story: c.story.name,
  repo: c.repo,
  branch: pr.branch,
  base: pr.base,
  commits: pr.commits,
  workspace: c.workspace.path,
  totalCostUsd,
  totalTokens,
  phases,
  resumeHint: `cd ${c.workspace.path} && claude --resume <sessionId>   # continue any phase interactively`,
} }];

// Every phase's error output lands here. Record the failure on the story, ping Slack, then
// fail the run. Extract Story may not have run yet (a step-1 failure), so fall back for the id.
let c;
try { c = $('Extract Story').first().json; }
catch (_) { try { c = $('Normalize & Validate').first().json; } catch (_2) { c = { storyId: 'unknown' }; } }
const storyName = c.story && c.story.name ? `: ${c.story.name}` : '';
const repo = c.repo ? ` (${c.repo})` : '';
const e = $input.first().json;
const raw = typeof e.error === 'string' ? e.error : (e.error?.message ?? e.message ?? JSON.stringify(e));
const phase = e.phase || (typeof $prevNode !== 'undefined' && $prevNode.name) || 'unknown step';
const reason = String(raw).split('\n')[0].replace(/\s*\[line \d+\]\s*$/, '').slice(0, 400);
let workspace = null;
try { workspace = $('Prepare Workspace').first().json.result?.path ?? null; } catch (_) { /* failed before it ran */ }
let pushed = null;
try { pushed = $('Run Nonprod Plan').first().json.result?.ref ?? null; } catch (_) { /* never pushed */ }
const ts = new Date().toISOString().replace('T', ' ').slice(0, 16) + 'Z';
const note = `[n8n ${ts}] Rally → Spec-Kit → Draft PR run failed at "${phase}": ${reason}. No PR was opened.` +
  (pushed ? ` Branch ${pushed} was pushed for the nonprod plan.` : '') +
  (workspace ? ` Local workspace: ${workspace}` : '');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const slackText = esc([
  `:x: *${c.storyId}${storyName}*${repo} — the Rally → Spec-Kit → Draft PR run FAILED at *${phase}*.`,
  reason,
  'No PR was opened.',
  pushed ? `Branch ${pushed} was pushed for the nonprod plan.` : '',
  workspace ? `Local workspace: ${workspace}` : '',
  `Open the run under Executions in n8n for the full trace.`,
].filter(Boolean).join('\n')).slice(0, 2900);
return [{ json: {
  kind: 'script', name: 'rally-append-note', label: 'Note Failure in Rally', timeoutMin: 2,
  args: [c.storyId, note],
  message: `${phase} failed: ${String(raw).slice(0, 3000)}`,
  slackText,
} }];

// Last ```json fenced block in a Claude reply, parsed.
const lastJson = (text, phase) => {
  const blocks = [...String(text ?? '').matchAll(/```json\s*([\s\S]*?)```/g)];
  if (!blocks.length) throw new Error(`${phase} did not end with a \`\`\`json block`);
  try { return JSON.parse(blocks[blocks.length - 1][1]); } catch (e) { throw new Error(`${phase} returned invalid JSON: ${e.message}`); }
};
const qa = $('Job: Discover Nonprod Plan').first().json.qa ?? [];
const t = lastJson($input.first().json.result, 'Discover Nonprod Plan');
const questions = (Array.isArray(t.questions) ? t.questions : []).filter((q) => q && String(q.question ?? '').trim());

if (questions.length) {
  if (qa.length >= 5) {
    throw new Error(`still ${questions.length} open nonprod-plan question(s) after ${qa.length} developer answers: ${questions.map((q) => q.question).join(' | ')}`);
  }
  return [{ json: { needsInput: true, skip: false, questions, qa, target: t } }];
}
if (t.skip === true) return [{ json: { needsInput: false, skip: true, qa, target: t } }];

// Guardrails: nonprod-plan.sh re-checks the first two, but fail here with a clear message.
const inputs = t.inputs ?? {};
const env = String(t.environment ?? '');
if (!/^[\w.-]+\.ya?ml$/.test(String(t.workflow ?? ''))) throw new Error(`nonprod target has no valid workflow file name: ${JSON.stringify(t.workflow)}`);
if (!['workflow_dispatch', 'push'].includes(t.trigger)) throw new Error(`nonprod target has an unsupported trigger: ${JSON.stringify(t.trigger)}`);
if (typeof inputs !== 'object' || Array.isArray(inputs) || !Object.values(inputs).every((v) => typeof v === 'string')) {
  throw new Error(`nonprod target inputs must be an object of strings: ${JSON.stringify(inputs)}`);
}
if (t.planOnly !== true || Object.values(inputs).some((v) => /\b(apply|destroy)\b/i.test(v))) {
  throw new Error(`refusing a nonprod target that is not plan-only: ${JSON.stringify(inputs)}`);
}
if (/(^|[^a-z])(prod|production|prd)([^a-z]|$)/i.test(env) && !/(non|pre)-?prod/i.test(env)) {
  throw new Error(`refusing: "${env}" looks like a production environment`);
}
return [{ json: { needsInput: false, skip: false, qa, target: { ...t, inputs } } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $('Build Context').first().json;
const p = $input.first().json;
const lines = p.questions.map((q, i) => [
  `${i + 1}. ${q.question}`,
  (q.options ?? []).length ? `   options: ${q.options.join(' / ')}` : '',
  q.recommendation ? `   Claude recommends: ${q.recommendation}` : '',
].filter(Boolean).join('\n'));
const slackText = esc([
  `*${c.storyId}: ${c.story.name}* needs your input before its nonprod Terraform plan runs.`,
  `Repo ${c.repo}, branch ${c.workspace.branch}.`,
  p.target?.rationale ? `_Claude so far:_ ${p.target.rationale}` : '',
  '',
  ...lines,
].filter((l) => l !== null).join('\n')).slice(0, 2900);
const formHtml = `<ol>${p.questions.map((q) => `<li><p>${esc(q.question)}</p>` +
  ((q.options ?? []).length ? `<p>Options: ${q.options.map(esc).join(' / ')}</p>` : '') +
  (q.recommendation ? `<p><em>Claude recommends: ${esc(q.recommendation)}</em></p>` : '') + '</li>').join('')}</ol>`;
return [{ json: { ...p, slackText, formHtml, questionText: lines.join('\n') } }];

// Timed out = the Wait node passed its input through without a form submission.
const answers = String($input.first().json.Answers ?? '').trim();
const p = $('Build Slack Questions').first().json;
if (!answers) throw new Error('no answer to the nonprod plan questions on Slack within 24h');
return [{ json: { qa: [...(p.qa ?? []), { question: p.questionText, answer: answers }] } }];

const c = $('Build Context').first().json;
const t = $('Parse Nonprod Target').first().json.target;
return [{ json: {
  kind: 'script',
  name: 'nonprod-plan',
  label: 'Run Nonprod Plan',
  args: [c.runDir, t.workflow, t.trigger, JSON.stringify(t.inputs ?? {}), '45'],
  timeoutMin: 60,
} }];

// Reached from a completed-but-unsuccessful run, or from the script's error output (dispatch
// refused, run never appeared, still running at the deadline). Claude gets MAX_AUTO_FIX tries on
// its own; after that every failure goes to the developer on Slack.
const MAX_AUTO_FIX = 2;
const j = $input.first().json;
const run = j.result && typeof j.result === 'object' ? j.result : null;
const raw = typeof j.error === 'string' ? j.error : (j.error?.message ?? j.message ?? '');
const reason = run
  ? `run ${run.runUrl} ended "${run.conclusion}" (${(run.jobs ?? []).filter((x) => x.conclusion !== 'success').map((x) => `${x.name}: ${x.conclusion}`).join(', ') || 'no failed jobs listed'})`
  : `nonprod-plan.sh failed: ${String(raw).split('\n')[0].slice(0, 600)}`;
return [{ json: { run, reason, detail: String(raw).slice(0, 3000), attempt: $runIndex + 1, autoFix: $runIndex < MAX_AUTO_FIX, guidance: '' } }];

const c = $('Build Context').first().json;
const guidance = String($input.first().json.guidance ?? '').trim(); // set when the developer chose "Fix"
const f = $('Plan Failed').first().json;
const t = $('Parse Nonprod Target').first().json.target;
const phase = `NONPROD PLAN — fix the failure.
The pipeline ran the nonprod Terraform plan for ${c.workspace.branch} and it did not succeed:
${f.reason}
Workflow ${t.workflow} (${t.trigger}), environment ${t.environment}, inputs ${JSON.stringify(t.inputs ?? {})}.
${f.run ? `Read the failed logs: gh run view ${f.run.runId} --log-failed (and gh run view ${f.run.runId} --json jobs).` : `Script output:\n${f.detail}`}

1. Find the root cause.
2. If it is caused by code or Terraform on this branch, fix it (terraform fmt / validate where
   relevant) and commit with message "${c.storyId}: fix nonprod terraform plan". Do not push;
   the pipeline pushes and re-runs the plan.
3. If it cannot be fixed from this branch (credentials / OIDC, IAM permissions, state lock,
   environment approval, runner, a wrong workflow input), change nothing and say what the
   developer has to do.
${guidance ? `\nThe developer sent this guidance over Slack. Follow it:\n${guidance}\n` : ''}
End your reply with a \`\`\`json fenced block {"fixed": true or false, "cause": "<one line>", "changes": "<what you changed, or empty>"}, then the STATUS line.`;
return [{ json: {
  kind: 'claude',
  label: 'Fix Nonprod Plan',
  model: c.models.dev,
  retryModel: c.models.retry,
  cwd: c.runDir,
  timeoutMin: 45,
  requireStatusOk: true,
  prompt: `${c.preamble}\n\n${phase}\n${c.statusRule}`,
} }];

// Last ```json fenced block in a Claude reply, parsed.
const lastJson = (text, phase) => {
  const blocks = [...String(text ?? '').matchAll(/```json\s*([\s\S]*?)```/g)];
  if (!blocks.length) throw new Error(`${phase} did not end with a \`\`\`json block`);
  try { return JSON.parse(blocks[blocks.length - 1][1]); } catch (e) { throw new Error(`${phase} returned invalid JSON: ${e.message}`); }
};
const r = lastJson($input.first().json.result, 'Fix Nonprod Plan');
return [{ json: { fixed: r.fixed === true, cause: String(r.cause ?? ''), changes: String(r.changes ?? '') } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $('Build Context').first().json;
const f = $('Plan Failed').first().json;
const t = $('Parse Nonprod Target').first().json.target;
// Present when Claude looked at this failure and could not fix it from the branch.
const fix = $input.first().json.fixed === false ? $input.first().json : null;
const slackText = esc([
  `*${c.storyId}: ${c.story.name}*: the nonprod Terraform plan failed (attempt ${f.attempt}). No PR has been opened.`,
  `Repo ${c.repo}, branch ${c.workspace.branch}, workflow ${t.workflow}, environment ${t.environment}.`,
  f.reason,
  fix ? `_Claude's diagnosis:_ ${fix.cause}` : '',
  '',
  'Open the form to choose: fix the code with your guidance, re-run the plan unchanged, pick a different workflow / environment, or abort.',
].filter(Boolean).join('\n')).slice(0, 2900);
return [{ json: { slackText } }];

const form = $input.first().json;
const d = String(form.Decision ?? '');
const guidance = String(form.Guidance ?? '').trim();
const f = $('Plan Failed').first().json;
const t = $('Parse Nonprod Target').first().json.target;
const decision = d.startsWith('Fix') ? 'fix' : d.startsWith('Re-run') ? 'rerun' : d.startsWith('Use a different') ? 'rediscover' : 'abort';
if (decision === 'abort') {
  return [{ json: { decision, phase: 'Nonprod Plan', error: d ? `developer aborted after the nonprod plan failed — ${f.reason}` : `no decision on the failed nonprod plan within 24h — ${f.reason}` } }];
}
const qa = decision === 'rediscover'
  ? [...($('Parse Nonprod Target').first().json.qa ?? []), {
      question: `The plan with workflow ${t.workflow}, environment ${t.environment}, inputs ${JSON.stringify(t.inputs ?? {})} failed (${f.reason}). What should be used instead?`,
      answer: guidance || '(no guidance given — find a different target)',
    }]
  : undefined;
return [{ json: { decision, guidance, qa } }];
